<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>Notification Preferences</title>
    <style>
      :root {
        color-scheme: light;
        --bg: #f4f7fb;
        --card: #ffffff;
        --text: #132238;
        --muted: #5b6b82;
        --border: #d9e2ef;
        --accent: #2563eb;
        --accent-soft: rgba(37, 99, 235, 0.08);
        --shadow: 0 20px 60px rgba(15, 23, 42, 0.08);
      }

      * {
        box-sizing: border-box;
      }

      body {
        margin: 0;
        min-height: 100vh;
        display: grid;
        place-items: center;
        padding: 24px;
        background:
          radial-gradient(circle at top, #e8f0ff 0%, transparent 38%),
          linear-gradient(180deg, #f8fbff 0%, var(--bg) 100%);
        color: var(--text);
        font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI",
          sans-serif;
      }

      #root {
        width: 100%;
        max-width: 640px;
      }

      .card {
        background: var(--card);
        border: 1px solid rgba(217, 226, 239, 0.9);
        border-radius: 24px;
        box-shadow: var(--shadow);
        overflow: hidden;
      }

      .card__header {
        padding: 32px 32px 0;
      }

      .eyebrow {
        display: inline-flex;
        align-items: center;
        gap: 8px;
        padding: 6px 12px;
        border-radius: 999px;
        background: var(--accent-soft);
        color: var(--accent);
        font-size: 0.875rem;
        font-weight: 600;
      }

      h1 {
        margin: 16px 0 8px;
        font-size: clamp(1.75rem, 3vw, 2.25rem);
        line-height: 1.1;
      }

      .subtitle {
        margin: 0;
        color: var(--muted);
        font-size: 1rem;
        line-height: 1.6;
      }

      form {
        padding: 24px 32px 32px;
      }

      .form-field {
        padding: 24px;
        border: 1px solid var(--border);
        border-radius: 18px;
        background: linear-gradient(180deg, #ffffff 0%, #fbfdff 100%);
      }

      .question {
        margin: 0 0 16px;
        font-size: 1.125rem;
        font-weight: 700;
      }

      .options {
        display: grid;
        gap: 12px;
        margin: 0;
        padding: 0;
        border: 0;
      }

      .option {
        position: relative;
      }

      .option input {
        position: absolute;
        inset: 0;
        opacity: 0;
        margin: 0;
        cursor: pointer;
      }

      .option label {
        display: flex;
        align-items: center;
        gap: 14px;
        width: 100%;
        padding: 16px 18px;
        border: 1px solid var(--border);
        border-radius: 14px;
        background: #fff;
        transition:
          border-color 0.2s ease,
          box-shadow 0.2s ease,
          transform 0.2s ease;
        cursor: pointer;
      }

      .option label::before {
        content: "";
        width: 18px;
        height: 18px;
        border: 2px solid #a8b7cc;
        border-radius: 50%;
        box-shadow: inset 0 0 0 4px #fff;
        flex: none;
        transition: border-color 0.2s ease, background-color 0.2s ease;
      }

      .option input:checked + label {
        border-color: var(--accent);
        background: var(--accent-soft);
        box-shadow: 0 10px 30px rgba(37, 99, 235, 0.08);
      }

      .option input:checked + label::before {
        border-color: var(--accent);
        background: var(--accent);
      }

      .option input:focus-visible + label {
        outline: 3px solid rgba(37, 99, 235, 0.2);
        outline-offset: 2px;
      }

      .actions {
        margin-top: 24px;
        display: flex;
        justify-content: flex-end;
      }

      button {
        border: 0;
        border-radius: 999px;
        padding: 14px 22px;
        background: linear-gradient(135deg, #2563eb, #1d4ed8);
        color: #fff;
        font: inherit;
        font-weight: 700;
        cursor: pointer;
        box-shadow: 0 12px 24px rgba(37, 99, 235, 0.25);
      }

      button:hover {
        filter: brightness(1.03);
      }

      button:focus-visible {
        outline: 3px solid rgba(37, 99, 235, 0.28);
        outline-offset: 3px;
      }
    </style>
  </head>
  <body>
    <div id="root"></div>

    <script>
      const h = (tag, props = {}, ...children) => {
        const el = document.createElement(tag);
        Object.entries(props).forEach(([key, value]) => {
          if (key === "className") el.className = value;
          else if (key === "textContent") el.textContent = value;
          else if (key.startsWith("on") && typeof value === "function") {
            el.addEventListener(key.slice(2).toLowerCase(), value);
          } else if (value !== false && value != null) {
            el.setAttribute(key, value);
          }
        });
        children.flat().forEach((child) => {
          if (child == null) return;
          el.appendChild(
            child instanceof Node ? child : document.createTextNode(String(child)),
          );
        });
        return el;
      };

      function RadioOption({ id, value, label, name, checked = false }) {
        return h(
          "div",
          { className: "option" },
          h("input", {
            type: "radio",
            id,
            name,
            value,
            checked,
            required: true,
          }),
          h("label", { for: id }, label),
        );
      }

      function NotificationForm() {
        const form = h(
          "form",
          {
            onsubmit: (event) => {
              event.preventDefault();
            },
          },
          h(
            "div",
            { className: "form-field" },
            h("p", {
              className: "question",
              textContent: "How do you prefer to receive notifications?",
            }),
            h(
              "fieldset",
              { className: "options" },
              RadioOption({
                id: "notification-email",
                name: "notification-preference",
                value: "Email",
                label: "Email",
              }),
              RadioOption({
                id: "notification-sms",
                name: "notification-preference",
                value: "SMS",
                label: "SMS",
              }),
              RadioOption({
                id: "notification-push",
                name: "notification-preference",
                value: "Push Notifications",
                label: "Push Notifications",
              }),
            ),
          ),
          h(
            "div",
            { className: "actions" },
            h("button", { type: "submit", textContent: "Submit" }),
          ),
        );

        return form;
      }

      function App() {
        return h(
          "main",
          { className: "card", "aria-labelledby": "page-title" },
          h(
            "div",
            { className: "card__header" },
            h("span", { className: "eyebrow", textContent: "Preferences" }),
            h("h1", { id: "page-title", textContent: "Notification settings" }),
            h("p", {
              className: "subtitle",
              textContent:
                "Choose the channel you'd like us to use when we send updates.",
            }),
          ),
          NotificationForm(),
        );
      }

      document.getElementById("root").appendChild(App());
    </script>
  </body>
</html>
